import { useId, type ComponentProps } from "react";
import { cn } from "./cn";

/** Smooth area sparkline with an end-point dot. Draws in the sage colour; the label is what a screen reader says. */
export function Sparkline({ values, width = 240, height = 56, label = "Trend", className, ...rest }: Omit<ComponentProps<"svg">, "viewBox" | "children" | "values"> & {
  /** The series, oldest first. Needs at least two values. */
  values: number[];
  /** Width of the drawing area in its own units; the SVG scales to its container. */
  width?: number;
  /** Height of the drawing area in its own units. */
  height?: number;
  label?: string;
}) {
  const gid = useId();
  const max = Math.max(...values, 1), n = values.length;
  const pts = values.map((v, i) => [(i / (n - 1)) * width, height - 6 - (v / max) * (height - 14)]);
  let d = `M${pts[0][0]},${pts[0][1]}`;
  for (let i = 1; i < n; i++) { const [x0, y0] = pts[i - 1], [x1, y1] = pts[i], cx = (x0 + x1) / 2; d += ` C${cx},${y0} ${cx},${y1} ${x1},${y1}`; }
  const last = pts[n - 1];
  return (
    <svg data-slot="sparkline" className={cn("spark", className)} viewBox={`0 0 ${width} ${height}`} role="img" aria-label={label} {...rest}>
      <defs><linearGradient id={gid} x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor="var(--sage)" stopOpacity=".35" /><stop offset="1" stopColor="var(--sage)" stopOpacity="0" /></linearGradient></defs>
      <line x1="0" x2={width} y1={height - 1} y2={height - 1} stroke="var(--line)" />
      <path d={`${d} L${width},${height} L0,${height}Z`} fill={`url(#${gid})`} />
      <path d={d} fill="none" stroke="var(--sage)" strokeWidth="2.2" strokeLinecap="round" />
      <circle cx={last[0] - 4} cy={last[1]} r="4.5" fill="var(--tile)" stroke="var(--sage)" strokeWidth="2.5" />
    </svg>
  );
}
